import {
  Fieldset as FieldsetPrimitive,
  useFieldset,
  useFieldsetContext,
} from '@ark-ui/solid/fieldset';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './Fieldset.module.css';

function FieldsetRoot(props: ComponentProps<typeof FieldsetPrimitive.Root>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldsetPrimitive.Root
      asChild={local.asChild}
      {...others}
      data-slot="fieldset-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldsetRootProvider(props: ComponentProps<typeof FieldsetPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldsetPrimitive.RootProvider
      asChild={local.asChild}
      {...others}
      data-slot="fieldset-root-provider"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldsetLegend(props: ComponentProps<typeof FieldsetPrimitive.Legend>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldsetPrimitive.Legend
      asChild={local.asChild}
      {...others}
      data-slot="fieldset-legend"
      class={clsx(styles.legend, local.class)}
    />
  );
}

function FieldsetHelperText(props: ComponentProps<typeof FieldsetPrimitive.HelperText>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldsetPrimitive.HelperText
      asChild={local.asChild}
      {...others}
      data-slot="fieldset-helper-text"
      class={clsx(styles.helperText, local.class)}
    />
  );
}

function FieldsetErrorText(props: ComponentProps<typeof FieldsetPrimitive.ErrorText>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldsetPrimitive.ErrorText
      asChild={local.asChild}
      {...others}
      data-slot="fieldset-error-text"
      class={clsx(styles.errorText, local.class)}
    />
  );
}

const Fieldset = Object.assign(FieldsetRoot, {
  Root: FieldsetRoot,
  RootProvider: FieldsetRootProvider,
  Context: FieldsetPrimitive.Context,
  Legend: FieldsetLegend,
  HelperText: FieldsetHelperText,
  ErrorText: FieldsetErrorText,
});

export { Fieldset, useFieldset, useFieldsetContext };

@layer moduix.components {
  .root,
  .legend,
  .helperText,
  .errorText {
    box-sizing: border-box;
  }

  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-fieldset-gap, var(--moduix-spacing-4));
    width: var(--moduix-fieldset-width, 100%);
    max-width: var(--moduix-fieldset-max-width, none);
    margin: var(--moduix-fieldset-margin, 0);
    padding: var(--moduix-fieldset-padding, 0);
    border-width: var(--moduix-fieldset-border-width, 0);
    border-style: var(--moduix-fieldset-border-style, solid);
    border-color: var(--moduix-fieldset-border-color, transparent);
    border-radius: var(--moduix-fieldset-radius, var(--moduix-radius-none));
    min-inline-size: 0;

    &[data-disabled] {
      opacity: var(--moduix-fieldset-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &[data-invalid] {
      border-color: var(--moduix-fieldset-border-color-invalid, var(--moduix-color-destructive));
    }
  }

  .legend {
    display: inline-block;
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    margin: var(--moduix-fieldset-legend-margin, 0);
    padding: var(--moduix-fieldset-legend-padding, 0 0 var(--moduix-spacing-3));
    color: var(--moduix-fieldset-legend-color, var(--moduix-color-foreground));
    font-size: var(--moduix-fieldset-legend-font-size, var(--moduix-text-lg));
    font-weight: var(--moduix-fieldset-legend-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-fieldset-legend-line-height, var(--moduix-line-height-text-lg));
  }

  .helperText,
  .errorText {
    overflow-wrap: anywhere;
    font-size: var(--moduix-fieldset-message-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-fieldset-message-line-height, var(--moduix-line-height-text-sm));
  }

  .helperText {
    color: var(--moduix-fieldset-helper-text-color, var(--moduix-color-muted-foreground));
  }

  .errorText {
    color: var(--moduix-fieldset-error-text-color, var(--moduix-color-destructive));
    font-weight: var(--moduix-fieldset-error-text-font-weight, var(--moduix-weight-medium));
  }
}
